css:
.mergeid-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a37;
    background: linear-gradient(165deg, #f6f4ef 0%, #eef2f3 55%, #e8eef0 100%);
    border-radius: 18px;
}

.mergeid-container * {
    box-sizing: border-box;
}

.mergeid-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f3b52 0%, #14687a 55%, #1f8a76 100%);
    color: #f3fbfa;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(15, 59, 82, 0.30);
}

.mergeid-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.mergeid-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd79a;
    background: rgba(255, 215, 154, 0.14);
    border: 1px solid rgba(255, 215, 154, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
}

.mergeid-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6ece9;
}

.mergeid-firms {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.mergeid-firm {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(31, 42, 55, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.mergeid-firm-stadhaven { border-left: 5px solid #2563a8; }
.mergeid-firm-nimbus { border-left: 5px solid #e08a1e; }

.mergeid-firm-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #0f3b52;
}

.mergeid-firm-stadhaven .mergeid-firm-name { color: #2563a8; }
.mergeid-firm-nimbus .mergeid-firm-name { color: #c8780f; }

.mergeid-firm-meta {
    font-size: 0.82rem;
    color: #5a6b7a;
    line-height: 1.4;
}

.mergeid-firm-plus {
    align-self: center;
    font-size: 1.6rem;
    font-weight: 800;
    color: #14687a;
}

.mergeid-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #46596b;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.mergeid-period-counter #currentDay,
.mergeid-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f8a76;
}

.mergeid-round-name {
    background: rgba(31, 138, 118, 0.14);
    color: #157561;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.mergeid-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b06d12;
    background: rgba(224, 138, 30, 0.14);
    border: 1px solid rgba(224, 138, 30, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.mergeid-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.mergeid-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.08);
    border-top: 4px solid #14687a;
}

.mergeid-card-ident { border-top-color: #1f8a76; }
.mergeid-card-retain { border-top-color: #2563a8; }
.mergeid-card-justice { border-top-color: #7d5fc0; }
.mergeid-card-integration { border-top-color: #e08a1e; }

.mergeid-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7d8d;
}

.mergeid-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0f3b52;
    font-variant-numeric: tabular-nums;
}

.mergeid-card-ident .mergeid-value { color: #1f8a76; }
.mergeid-card-retain .mergeid-value { color: #2563a8; }
.mergeid-card-justice .mergeid-value { color: #7d5fc0; }
.mergeid-card-integration .mergeid-value { color: #c8780f; }

.mergeid-sublabel {
    font-size: 0.76rem;
    color: #76889a;
    line-height: 1.35;
}

.mergeid-card-retain.mergeid-retain-danger { border-top-color: #d64545; }
.mergeid-card-retain.mergeid-retain-danger .mergeid-value { color: #d64545; }
.mergeid-card-retain.mergeid-retain-good { border-top-color: #1f8a76; }
.mergeid-card-retain.mergeid-retain-good .mergeid-value { color: #1f8a76; }

.mergeid-threat-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e0e6ea;
    color: #46596b;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.mergeid-threat-bar #threatDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #d64545;
    font-weight: 800;
}

.mergeid-threat-bar.mergeid-threat-low #threatDisplay { color: #1f8a76; }
.mergeid-threat-bar.mergeid-threat-mid #threatDisplay { color: #c8780f; }

.mergeid-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1f8a76;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.07);
}

.mergeid-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.mergeid-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0f3b52;
    margin-bottom: 6px;
}

.mergeid-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3c4d5e;
}

.mergeid-briefing-text strong { color: #14687a; }
.mergeid-briefing-text em { color: #c8780f; font-style: italic; }

.mergeid-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.07);
}

.mergeid-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0f3b52;
    border-bottom: 2px solid #e7ecef;
    padding-bottom: 8px;
}

.mergeid-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3d4e;
    margin: 14px 0 6px;
}

.mergeid-container select,
.mergeid-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c8d3da;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1f2a37;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.mergeid-container select:focus,
.mergeid-container input[type="number"]:focus {
    outline: none;
    border-color: #1f8a76;
    box-shadow: 0 0 0 3px rgba(31, 138, 118, 0.16);
}

.mergeid-container select option {
    background-color: #ffffff;
    color: #1f2a37;
}

.mergeid-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f8a76;
}

.mergeid-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #46596b;
    margin-top: 4px;
}

.mergeid-range-readout span:nth-child(2) {
    color: #1f8a76;
    font-weight: 800;
}

.mergeid-hint {
    font-size: 0.8rem;
    color: #76889a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.mergeid-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.mergeid-container .btn-primary {
    background: linear-gradient(135deg, #14687a 0%, #1f8a76 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(20, 104, 122, 0.32);
}

.mergeid-container .btn-primary:hover {
    filter: brightness(1.07);
}

.mergeid-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c8d3da;
    color: #5a6b7a;
    background: transparent;
}

.mergeid-coach {
    background: linear-gradient(160deg, #0f3b52 0%, #11455c 100%);
    color: #e3f1f0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(15, 59, 82, 0.24);
}

.mergeid-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffd79a;
    margin-bottom: 8px;
}

.mergeid-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.mergeid-coach-body strong { color: #7fe0cf; }
.mergeid-coach-body em { color: #ffd79a; font-style: italic; }

.mergeid-history,
.mergeid-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 42, 55, 0.07);
}

.mergeid-history h3,
.mergeid-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0f3b52;
}

.mergeid-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3c4d5e;
}

.mergeid-container table#usfHistoryTable th {
    background: #eef4f3;
    color: #14687a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d8e3e1;
}

.mergeid-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f3;
    color: #3c4d5e;
}

.mergeid-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7faf9;
}

.mergeid-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .mergeid-container {
        padding: 14px;
    }
    .mergeid-header h1 {
        font-size: 1.7rem;
    }
    .mergeid-firms {
        flex-direction: column;
    }
    .mergeid-firm-plus {
        transform: rotate(90deg);
    }
    .mergeid-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .mergeid-value {
        font-size: 2rem;
    }
    .mergeid-clock {
        margin-left: 0;
    }
    .mergeid-period-counter {
        font-size: 0.88rem;
    }
    .mergeid-threat-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .mergeid-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion scorecard (append-only, namespaced .mgi-cm-*) */
.mgi-cm { margin-top: 8px; }
.mgi-cm-incomplete { text-align: center; color: #0f3b52; font-size: 1rem; padding: 18px; }
.mgi-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.mgi-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #0f3b52 0%, #14687a 55%, #1f8a76 140%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(15,59,82,0.28); }
.mgi-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.mgi-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.mgi-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #a9dccf; }
.mgi-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #f2f8f9; border: 1px solid #d5e6e6; border-radius: 14px; padding: 14px 20px; }
.mgi-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5f8590; }
.mgi-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #0f3b52; margin-top: 4px; line-height: 1.15; }
.mgi-cm-section { margin-bottom: 16px; }
.mgi-cm-section-h { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700; color: #14687a; margin-bottom: 8px; border-bottom: 1px solid #d5e6e6; padding-bottom: 4px; }
.mgi-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.mgi-cm-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; border: 1px solid transparent; }
.mgi-cm-ok { background: #e2f1ee; color: #0f3b52; border-color: #bfe0d6; }
.mgi-cm-no { background: #fbeede; color: #98630c; border-color: #f0d3a2; }
.mgi-cm-ico { font-weight: 800; }
.mgi-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.mgi-cm-kpi { background: #fbfdfd; border: 1px solid #d5e6e6; border-radius: 12px; padding: 12px 10px; text-align: center; }
.mgi-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #14687a; line-height: 1; }
.mgi-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #234; margin-top: 6px; }
.mgi-cm-kpi-sub { font-size: 0.68rem; color: #5f8590; margin-top: 2px; }
.mgi-cm-insights { margin: 0; padding-left: 20px; color: #0f3b52; }
.mgi-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
@media (max-width: 620px) { .mgi-cm-kpis { grid-template-columns: repeat(2, 1fr); } }

