(function() {
    'use strict';

    class MergeIdentitiesAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Merging Identities`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Lowlands Logistics Group).
            this.AT_RISK = 250;          // ~250 engineers at elevated flight risk (22% of 1,150)
            this.TOP_TALENT = 50;        // losing the top 50 slips the roadmap 6–9 months
            this.SYNERGY = 22;           // EUR 22M of synergies at risk
            this.START_IDENT = 34;       // day-1 identification with Lowlands (%)
            this.START_JUSTICE = 5.2;    // day-1 perceived justice (/10)
            this.RETENTION_CAP = 6;      // EUR 6M targeted retention budget

            // Concept truths.
            this.TRUE_THREAT = `both`;
            this.TRUE_NARRATIVE = `dual`;
            this.TRUE_PHILOSOPHY = `continuity`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ident: this.START_IDENT,        // % identifying with Lowlands
                    retained: 0,                     // engineers retained of the 250 at-risk
                    justice: this.START_JUSTICE,     // perceived justice (/10)
                    integration: 0,                  // platform-roadmap progress (%)
                    threat: 72,                      // identity-threat index 0–100 (lower safer)
                    dominanceRun: false,             // pushed the dominance pattern
                    separationRun: false,            // separation paralysis
                    topTalentLost: false,            // lost the critical top 50
                    retentionSpent: 0,               // EUR M committed to retention
                    identHistory: [this.START_IDENT],
                    retainHistory: [0],
                    justiceHistory: [this.START_JUSTICE],
                    integrationHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    threat: `nimbus`,
                    weight: `ops`,
                    posture: `absorb`,
                    voice: 40,
                    narrative: `rebrand`,
                    symbols: `erase`,
                    pace: 50,
                    standards: `nimbus`,
                    pay: `freeze`,
                    lead: `nimbus`,
                    justice: `intranet`,
                    retention: 0,
                    board: `speed`,
                    philosophy: `dominance`,
                    probe: `defend`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const th = document.getElementById(`threatInput`);
                const wt = document.getElementById(`weightInput`);
                const po = document.getElementById(`postureInput`);
                const vo = document.getElementById(`voiceInput`);
                if (th) decisions.threat = th.value;
                if (wt) decisions.weight = wt.value;
                if (po) decisions.posture = po.value;
                if (vo) decisions.voice = parseInt(vo.value, 10);
                if (!Number.isFinite(decisions.voice) || decisions.voice < 0 || decisions.voice > 100) {
                    warn(`warn_voice_range`); return false;
                }
            } else if (round === 2) {
                const na = document.getElementById(`narrativeInput`);
                const sy = document.getElementById(`symbolsInput`);
                const pa = document.getElementById(`paceInput`);
                if (na) decisions.narrative = na.value;
                if (sy) decisions.symbols = sy.value;
                if (pa) decisions.pace = parseInt(pa.value, 10);
                if (!Number.isFinite(decisions.pace) || decisions.pace < 0 || decisions.pace > 100) {
                    warn(`warn_pace_range`); return false;
                }
            } else if (round === 3) {
                const st = document.getElementById(`standardsInput`);
                const py = document.getElementById(`payInput`);
                const le = document.getElementById(`leadInput`);
                const ju = document.getElementById(`justiceInput`);
                const re = document.getElementById(`retentionInput`);
                if (st) decisions.standards = st.value;
                if (py) decisions.pay = py.value;
                if (le) decisions.lead = le.value;
                if (ju) decisions.justice = ju.value;
                if (re) decisions.retention = parseFloat(re.value);
                if (!Number.isFinite(decisions.retention) || decisions.retention < 0) {
                    warn(`warn_retention_value`); return false;
                }
            } else if (round === 4) {
                const bo = document.getElementById(`boardInput`);
                const ph = document.getElementById(`philosophyInput`);
                const pr = document.getElementById(`probeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (bo) decisions.board = bo.value;
                if (ph) decisions.philosophy = ph.value;
                if (pr) decisions.probe = pr.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite (was computed only in getPerformanceSummary and discarded).
            const ident = Math.round(ds.ident);
            const retained = Math.round(ds.retained);
            const justice = Math.round(ds.justice * 10) / 10;
            const integration = Math.round(ds.integration);
            const retainScore = (retained / this.AT_RISK) * 100;
            const justiceScore = justice * 10;
            return Math.round(ident * 0.28 + retainScore * 0.30 + justiceScore * 0.22 + integration * 0.20);
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let identDelta = 0, justiceDelta = 0, integrationDelta = 0, threatDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the identity landscape (Common Error: misreading where threat sits).
                switch (d.threat) {
                    case `both`: justiceDelta += 0.4; threatDelta -= 8; coachKey = `coach_r1_both`; break;
                    case `stadhaven`: threatDelta -= 2; coachKey = `coach_r1_stadhaven`; break;
                    case `nimbus`: threatDelta += 5; coachKey = `coach_r1_nimbus`; break;
                    case `neither`: threatDelta += 8; coachKey = `coach_r1_neither`; break;
                }

                switch (d.weight) {
                    case `symbols`: identDelta += 3; threatDelta -= 5; break;
                    case `ops`: threatDelta += 4; coachKey = `coach_r1_ops`; break;
                    case `none`: threatDelta += 7; coachKey = `coach_r1_nosymbol`; break;
                }

                switch (d.posture) {
                    case `listen`: identDelta += 4; justiceDelta += 0.6; threatDelta -= 7; if (d.threat === `both`) coachKey = `coach_r1_sharp`; break;
                    case `absorb`: identDelta -= 4; justiceDelta -= 0.6; threatDelta += 9; ds.dominanceRun = true; coachKey = `coach_r1_absorb`; break;
                    case `freeze`: integrationDelta -= 2; threatDelta += 2; ds.separationRun = true; coachKey = `coach_r1_freeze`; break;
                }

                // Voice = procedural fairness lever from day one.
                if (d.voice >= 60) { justiceDelta += 0.6; threatDelta -= 5; }
                else if (d.voice <= 25) { justiceDelta -= 0.4; threatDelta += 4; }

                summaryKey = (d.threat === `both` && d.weight === `symbols` && d.posture === `listen`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // The central choice: continuity vs change (Common Errors 1 & 2).
                const pace = d.pace / 100;

                if (d.narrative === `rebrand`) {
                    // Dominance pattern — identification DROPS, threat spikes (decision tree #1).
                    ds.dominanceRun = true;
                    identDelta -= 8 - (1 - pace) * 4;        // faster = worse
                    threatDelta += 18 * pace + 6;
                    justiceDelta -= 1.0;
                    integrationDelta += 12 * pace;            // it does push integration on paper
                    coachKey = `coach_r2_rebrand`;
                } else if (d.narrative === `separate`) {
                    // Separation paralysis — no synergy (decision tree #2).
                    ds.separationRun = true;
                    identDelta += 2;
                    threatDelta -= 4;
                    integrationDelta -= 6 + (1 - pace) * 4;   // slower = even less progress
                    coachKey = `coach_r2_separate`;
                } else { // dual
                    // Sense of continuity + superordinate identity — the modelled path.
                    identDelta += 11;
                    justiceDelta += 0.9;
                    threatDelta -= 14;
                    integrationDelta += 16 + pace * 12;        // continuity that still genuinely integrates
                    coachKey = `coach_r2_dual`;
                    // Pace must match: a moderate pace serves the dual narrative best.
                    if (pace >= 0.85) { threatDelta += 6; identDelta -= 3; coachKey = `coach_r2_dualfast`; }
                    else if (pace <= 0.2) { integrationDelta -= 6; coachKey = `coach_r2_dualslow`; }
                }

                // Symbolic landmines (decision tree #6).
                switch (d.symbols) {
                    case `deliberate`: identDelta += 6; threatDelta -= 6; justiceDelta += 0.3; break;
                    case `erase`: identDelta -= 4; threatDelta += 7; if (d.narrative !== `rebrand`) coachKey = `coach_r2_symbolerase`; break;
                    case `ignore`: identDelta -= 2; threatDelta += 4; coachKey = `coach_r2_symbolignore`; break;
                }

                summaryKey = (d.narrative === `dual` && d.symbols === `deliberate`) ? `sum_r2_good` :
                             (d.narrative === `rebrand` ? `sum_r2_dominance` :
                             (d.narrative === `separate` ? `sum_r2_separation` : `sum_r2_weak`));
            } else if (round === 3) {
                // Justice in action — the three flashpoints (Common Errors 3 & 4).
                let nimbusSignals = 0;
                if (d.standards === `nimbus`) nimbusSignals++;
                if (d.lead === `nimbus`) nimbusSignals++;
                if (d.pay === `leveldown`) nimbusSignals++; // levelling Nimbus down still signals a winner-takes-all spreadsheet call against the absorbed

                // (a) Engineering standards / toolchain.
                switch (d.standards) {
                    case `bestofboth`: identDelta += 5; justiceDelta += 0.6; threatDelta -= 6; integrationDelta += 10; break;
                    case `nimbus`: threatDelta += 5; integrationDelta += 6; break;   // modern, but a signal Stadhaven lost
                    case `stadhaven`: threatDelta += 4; integrationDelta += 2; break; // loyalty over merit, slows the modern roadmap
                }

                // (b) Titles & the ~8% pay gap.
                switch (d.pay) {
                    case `levelup`: justiceDelta += 1.1; threatDelta -= 7; identDelta += 3; break;
                    case `leveldown`: justiceDelta -= 1.0; threatDelta += 8; break;
                    case `freeze`: justiceDelta -= 0.4; threatDelta += 4; coachKey = `coach_r3_payfreeze`; break;
                }

                // (c) Who leads the merged platform org.
                switch (d.lead) {
                    case `fairprocess`: justiceDelta += 0.9; threatDelta -= 6; identDelta += 3; integrationDelta += 7; break;
                    case `nimbus`: threatDelta += 4; integrationDelta += 4; break;
                    case `stadhaven`: justiceDelta += 0.2; integrationDelta -= 1; break;
                }

                // The three justice TYPES — process & explanation buffer threat (decision tree #3 & #4).
                switch (d.justice) {
                    case `threefold`: justiceDelta += 1.6; threatDelta -= 10; identDelta += 4; break;
                    case `intranet`: justiceDelta -= 0.8; threatDelta += 6; coachKey = `coach_r3_intranet`; break;
                    case `silent`: justiceDelta -= 1.2; threatDelta += 9; identDelta -= 2; coachKey = `coach_r3_silent`; break;
                }

                // Three Nimbus signals in a row = the technical-only trap (decision tree #3).
                if (nimbusSignals >= 3 && d.justice !== `threefold`) {
                    threatDelta += 8; identDelta -= 5; coachKey = `coach_r3_technical`;
                } else if (d.standards === `bestofboth` && d.pay === `levelup` && d.lead === `fairprocess` && d.justice === `threefold`) {
                    coachKey = `coach_r3_justice`;
                }

                summaryKey = (d.standards === `bestofboth` && d.pay === `levelup` && d.lead === `fairprocess` && d.justice === `threefold`) ? `sum_r3_good` :
                             (nimbusSignals >= 3 ? `sum_r3_technical` :
                             (d.justice === `silent` || d.justice === `intranet` ? `sum_r3_process` : `sum_r3_weak`));

                // Retention budget for the at-risk engineers.
                ds.retentionSpent = Math.min(this.RETENTION_CAP, Math.round((ds.retentionSpent + d.retention) * 10) / 10);
                if (d.retention >= 6) { threatDelta -= 6; justiceDelta += 0.3; }
                else if (d.retention <= 0) { threatDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r3_noretention`; }
            } else if (round === 4) {
                // Land the 100 days before the board / town hall.
                switch (d.philosophy) {
                    case `continuity`: identDelta += 6; justiceDelta += 0.6; threatDelta -= 8; integrationDelta += 7; coachKey = `coach_r4_continuity`; break;
                    case `dominance`: identDelta -= 6; threatDelta += 9; justiceDelta -= 0.6; ds.dominanceRun = true; coachKey = `coach_r4_dominance`; break;
                    case `separation`: integrationDelta -= 6; threatDelta += 2; ds.separationRun = true; coachKey = `coach_r4_separation`; break;
                }

                switch (d.board) {
                    case `balanced`: identDelta += 4; justiceDelta += 0.4; threatDelta -= 5; integrationDelta += 4; break;
                    case `speed`: integrationDelta += 3; threatDelta += 5; justiceDelta -= 0.4; coachKey = `coach_r4_speed`; break;
                    case `harmony`: integrationDelta -= 4; identDelta += 1; coachKey = `coach_r4_harmony`; break;
                }

                switch (d.probe) {
                    case `own`: justiceDelta += 0.8; threatDelta -= 6; identDelta += 3; if (d.philosophy === `continuity`) coachKey = `coach_r4_own`; break;
                    case `defend`: justiceDelta -= 0.4; threatDelta += 4; coachKey = `coach_r4_defend`; break;
                    case `blame`: justiceDelta -= 1.0; threatDelta += 7; identDelta -= 3; coachKey = `coach_r4_blame`; break;
                }

                if (d.conviction >= 60) { justiceDelta += 0.4; threatDelta -= 4; }
                else if (d.conviction <= 25) { justiceDelta -= 0.3; threatDelta += 4; }

                summaryKey = (d.philosophy === `continuity` && d.board === `balanced` && d.probe === `own`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply identity, justice, integration deltas (clamped). ----
            ds.ident = Math.max(0, Math.min(100, Math.round((ds.ident + identDelta) * 10) / 10));
            ds.justice = Math.max(0, Math.min(10, Math.round((ds.justice + justiceDelta) * 10) / 10));
            ds.integration = Math.max(0, Math.min(100, Math.round(ds.integration + integrationDelta)));
            ds.threat = Math.max(0, Math.min(100, Math.round(ds.threat + threatDelta)));

            // ---- Retention is DERIVED: engineers stay when identity threat is low,
            // justice is high, they identify with the new entity, and retention is funded.
            // Of the 250 at-risk engineers, model how many you keep this round. ----
            const safety = (100 - ds.threat) / 100;                 // 0..1
            const justiceFactor = ds.justice / 10;                  // 0..1
            const identFactor = ds.ident / 100;                     // 0..1
            const moneyFactor = 0.6 + 0.4 * (ds.retentionSpent / this.RETENTION_CAP); // 0.6..1.0
            const keepShare = Math.max(0, Math.min(1,
                (0.45 * safety + 0.30 * justiceFactor + 0.25 * identFactor) * moneyFactor
            ));
            ds.retained = Math.round(this.AT_RISK * keepShare);

            // Losing the top 50 caps integration progress (roadmap slip 6–9 months).
            if (ds.retained < (this.AT_RISK - this.TOP_TALENT)) {
                ds.topTalentLost = true;
                ds.integration = Math.min(ds.integration, 45);      // roadmap stalls without the critical talent
            } else {
                ds.topTalentLost = false;
            }

            ds.identHistory.push(ds.ident);
            ds.retainHistory.push(ds.retained);
            ds.justiceHistory.push(ds.justice);
            ds.integrationHistory.push(ds.integration);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 - persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                ident: ds.ident,
                identDelta: Math.round(identDelta * 10) / 10,
                retained: ds.retained,
                justice: ds.justice,
                justiceDelta: Math.round(justiceDelta * 10) / 10,
                integration: ds.integration,
                integrationDelta: Math.round(integrationDelta),
                threat: ds.threat,
                topTalentLost: ds.topTalentLost,
                retentionSpent: ds.retentionSpent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _threatLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`threat_high`);
            if (v >= 35) return t(`threat_mid`);
            return t(`threat_low`);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`identDisplay`, `domainState.ident`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`retainDisplay`, `domainState.retained`, (v) => {
                const r = Math.round(Number(v));
                const card = document.querySelector(`.mergeid-card-retain`);
                if (card) {
                    card.classList.toggle(`mergeid-retain-danger`, r < (self.AT_RISK - self.TOP_TALENT));
                    card.classList.toggle(`mergeid-retain-good`, r >= (self.AT_RISK - 25));
                }
                return `${r} / ${self.AT_RISK}`;
            });

            uiManager.bind(`justiceDisplay`, `domainState.justice`, (v) => self._fmtJustice(Number(v)));
            uiManager.bind(`integrationDisplay`, `domainState.integration`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`threatDisplay`, `domainState.threat`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.mergeid-threat-bar`);
                if (bar) {
                    bar.classList.toggle(`mergeid-threat-low`, n < 35);
                    bar.classList.toggle(`mergeid-threat-mid`, n >= 35 && n < 60);
                }
                return self._threatLabel(n);
            });

            // Voice slider readout.
            const vo = document.getElementById(`voiceInput`);
            const voReadout = document.getElementById(`voiceReadout`);
            if (vo && voReadout) {
                voReadout.textContent = vo.value;
                vo.addEventListener(`input`, function() { voReadout.textContent = vo.value; });
            }

            // Pace slider readout.
            const pa = document.getElementById(`paceInput`);
            const paReadout = document.getElementById(`paceReadout`);
            if (pa && paReadout) {
                paReadout.textContent = pa.value;
                pa.addEventListener(`input`, function() { paReadout.textContent = pa.value; });
            }
        }

        _fmtJustice(v) {
            // Locale-aware one-decimal score: en "5.2", es "5,2".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = v.toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

