        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.identHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Justice is /10 — scale ×10 to share the 0–100 axis with the percentages.
            const justiceScaled = ds.justiceHistory.map((v) => Math.round(v * 10));
            return {
                mergeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.identHistory.map((v) => Math.round(v)) },
                        { data: ds.integrationHistory },
                        { data: justiceScaled }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const ident = Math.round(ds.ident);
            const retained = Math.round(ds.retained);
            const justice = Math.round(ds.justice * 10) / 10;
            const integration = Math.round(ds.integration);
            const topTalentLost = ds.topTalentLost;

            // Composite: identification, retention, justice, integration — balanced.
            const retainScore = (retained / this.AT_RISK) * 100;
            const justiceScore = justice * 10;
            // v1.1.0 - reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const identified = ident >= 55;
            const retainedWell = retained >= (this.AT_RISK - this.TOP_TALENT);
            const fairlyDone = justice >= 7;
            const integrated = integration >= 50;

            let pattern = `separation`;
            if (ds.dominanceRun && !ds.separationRun) pattern = `dominance`;
            else if (identified && integrated && fairlyDone) pattern = `integration`;
            else if (ds.separationRun && integration < 45) pattern = `separation`;
            else pattern = `mixed`;

            // v1.1.0 - tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_valuelost`;
            if (identified && retainedWell && fairlyDone && integrated && composite >= 75) tierKey = `grade_integration`;
            else if (retainedWell && fairlyDone && pattern !== `dominance`) tierKey = `grade_talentheld`;
            else if (ds.dominanceRun && !retainedWell) tierKey = `grade_dominance`;
            else if (ds.separationRun && integration < 45) tierKey = `grade_separation`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (identified && retainedWell && fairlyDone && integrated) insights.push(window.mySimulation.t(`insight_integration`));
            else if (pattern === `dominance`) insights.push(window.mySimulation.t(`insight_dominance`));
            else if (pattern === `separation`) insights.push(window.mySimulation.t(`insight_separation`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (topTalentLost) insights.push(window.mySimulation.t(`insight_toptalent`));
            if (!fairlyDone) insights.push(window.mySimulation.t(`insight_justice_low`));
            if (ident < 45) insights.push(window.mySimulation.t(`insight_ident_low`));
            if (identified && retainedWell && integration < 50) insights.push(window.mySimulation.t(`insight_harmony_cost`));
            if (integration >= 60 && !retainedWell) insights.push(window.mySimulation.t(`insight_fast_cost`));

            return {
                ident: ident,
                retained: retained,
                justice: justice,
                integration: integration,
                identified: identified,
                retainedWell: retainedWell,
                fairlyDone: fairlyDone,
                integrated: integrated,
                topTalentLost: topTalentLost,
                pattern: pattern,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="mgi-cm"><p class="mgi-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="mgi-cm-chip ` + (ok ? `mgi-cm-ok` : `mgi-cm-no`) + `">` +
                `<span class="mgi-cm-ico">` + (ok ? `✓` : `✗`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="mgi-cm-kpi"><div class="mgi-cm-kpi-val">` + val +
                `</div><div class="mgi-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="mgi-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="mgi-cm">` +
  `<div class="mgi-cm-head">` +
    `<div class="mgi-cm-score"><div class="mgi-cm-score-num">` + Math.round(s.composite) +
       `<span class="mgi-cm-score-den">/100</span></div>` +
       `<div class="mgi-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="mgi-cm-verdict"><div class="mgi-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="mgi-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="mgi-cm-section"><div class="mgi-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="mgi-cm-chips">` + chip(!!s.identified, t(`cm_t_ident`)) + chip(!!s.retainedWell, t(`cm_t_retained`)) +
      chip(!!s.fairlyDone, t(`cm_t_justice`)) + chip(!!s.integrated, t(`cm_t_integration`)) + `</div></div>` +
  `<div class="mgi-cm-section"><div class="mgi-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="mgi-cm-kpis">` +
      kpi(t(`cm_lbl_ident`), Math.round(s.ident), t(`cm_sub_ident`)) +
      kpi(t(`cm_lbl_retained`), Math.round(s.retained), t(`cm_sub_retained`)) +
      kpi(t(`cm_lbl_justice`), Number(s.justice).toFixed(1), t(`cm_sub_justice`)) +
      kpi(t(`cm_lbl_integration`), Math.round(s.integration), t(`cm_sub_integration`)) +
    `</div></div>` +
  (insights ? `<div class="mgi-cm-section"><div class="mgi-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="mgi-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.topTalentLost) return window.mySimulation.t(`hint_toptalent`);
            if (ds.threat >= 65) return window.mySimulation.t(`hint_threat`);
            if (ds.dominanceRun && ds.ident < 45) return window.mySimulation.t(`hint_dominance`);
            if (ds.separationRun && state.currentPeriod >= 2 && ds.integration < 30) return window.mySimulation.t(`hint_separation`);
            if (ds.justice < 5 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_justice`);
            if (ds.ident >= 55 && ds.justice >= 7 && ds.integration >= 50) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.ident`, label: `Identify`, i18nKey: `col_ident`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.retained`, label: `Retained`, i18nKey: `col_retained`, formatter: (v) => `${Math.round(v)}/${self.AT_RISK}` },
                { key: `results.justice`, label: `Justice`, i18nKey: `col_justice`, formatter: (v) => self._fmtJustice(Number(v)) },
                { key: `results.integration`, label: `Integration`, i18nKey: `col_integration`, formatter: (v) => `${Math.round(v)}%` }
            ];
        }

