                    cm_missed:              `missed`,
                    cm_incomplete:          `Finish all four rounds to see your 100-day debrief.`,
                    cm_t_ident:             `Identification ≥ 55`,
                    cm_t_retained:          `Retained ≥ 200 of 250`,
                    cm_t_justice:           `Justice ≥ 7`,
